function trail(x,y){
const road=layout().road;
if(road==='capital')return Math.abs(x-14.5)<2.2||Math.abs(y-14)<1.8||(x>7&&x<23&&y>8&&y<21);
if(road==='forest')return Math.abs(x-(14.5+3*Math.sin(y*.28)))<1.35||Math.abs(y-14)<1.05;
if(road==='field')return Math.abs(y-(14.5+2.6*Math.sin(x*.2)))<1.45||Math.abs(x-14.5)<1.1;
if(road==='rail')return Math.abs(x-14.5)<1.35||Math.abs(y-14)<1.35||Math.abs(x-7.5)<.7;
return Math.abs(Math.hypot(x-14.5,y-14)-7)<1.1||Math.abs(x-14.5)<1.2;
}

